import { mkdir, writeFile } from "node:fs/promises";
import { dirname, resolve } from "node:path";
import { build } from "esbuild";

const root = resolve(import.meta.dirname, "..");
const entry = resolve(root, "src/runtime/injection/entry.ts");
const outFile = resolve(root, "src/generated/injection-bundle.ts");

const result = await build({
  entryPoints: [entry],
  bundle: true,
  format: "esm",
  platform: "browser",
  target: "esnext",
  write: false,
  minify: false,
  legalComments: "none",
  logLevel: "warning",
});

let source = "";
for (const file of result.outputFiles ?? []) {
  source += file.text;
}

const moduleSource = `// Generated by scripts/build-injection-bundle.mjs — do not edit.\n// The cheerio/domino/turndown bundle that travels into the Dynamic Worker.\nexport const INJECTION_BUNDLE_SOURCE = ${JSON.stringify(source)};\n`;

await mkdir(dirname(outFile), { recursive: true });
await writeFile(outFile, moduleSource);
console.log(`wrote ${outFile} (${source.length} bytes of bundle source)`);
